package xclbin

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// Offsets used by the parser must match xclbin.h (testdata/abi/xdna_abi.json, generated by gcc).
func TestLayoutMatchesCHeader(t *testing.T) {
	raw, err := os.ReadFile("../../testdata/abi/xdna_abi.json")
	if err != nil {
		t.Fatal(err)
	}
	var g map[string]json.RawMessage
	json.Unmarshal(raw, &g)
	get := func(st string) (size int, fields map[string]int) {
		var v struct {
			Size   int            `json:"size"`
			Fields map[string]int `json:"fields"`
		}
		if err := json.Unmarshal(g[st], &v); err != nil {
			t.Fatalf("%s: %v", st, err)
		}
		return v.Size, v.Fields
	}
	check := func(name string, got, want int) {
		t.Helper()
		if got != want {
			t.Errorf("%s: Go %d, C %d", name, got, want)
		}
	}
	_, axlf := get("axlf")
	check("axlf.m_header", axlfHeaderOffset, axlf["m_header"])
	check("axlf.m_sections", axlfSectionsOffset, axlf["m_sections"])
	size, hdr := get("axlf_header")
	check("sizeof(axlf_header)", axlfHeaderSize, size)
	check("axlf_header.uuid", 112, hdr["uuid"])
	check("axlf_header.m_numSections", 144, hdr["m_numSections"])
	size, sh := get("axlf_section_header")
	check("sizeof(axlf_section_header)", sectionHeaderSize, size)
	check("m_sectionOffset", 24, sh["m_sectionOffset"])
	check("m_sectionSize", 32, sh["m_sectionSize"])
	_, ipl := get("ip_layout")
	check("ip_layout.m_ip_data", ipLayoutDataOffset, ipl["m_ip_data"])
	size, ipd := get("ip_data")
	check("sizeof(ip_data)", ipDataSize, size)
	check("ip_data.properties", 4, ipd["properties"])
	check("ip_data.m_name", 16, ipd["m_name"])
	size, ap := get("aie_partition")
	check("sizeof(aie_partition)", aiePartitionSize, size)
	check("operations_per_cycle", 8, ap["operations_per_cycle"])
	check("aie_partition.info", 32, ap["info"])
	check("aie_partition.aie_pdi", 120, ap["aie_pdi"])
	_, info := get("aie_partition_info")
	check("info.start_columns", 8, info["start_columns"]) // 32 + 8 = 40
	size, pdi := get("aie_pdi")
	check("sizeof(aie_pdi)", aiePDISize, size)
	check("pdi_image", 16, pdi["pdi_image"])
	check("cdo_groups", 24, pdi["cdo_groups"])
	size, cg := get("cdo_group")
	check("sizeof(cdo_group)", cdoGroupSize, size)
	check("cdo_type", 4, cg["cdo_type"])
	check("pdi_id", 8, cg["pdi_id"])
	check("dpu_kernel_ids", 16, cg["dpu_kernel_ids"])
}

func spec() Spec {
	return Spec{
		UUID: [16]byte{1, 2, 3},
		Kernels: []Kernel{{Name: "MLIR_AIE", Type: "dpu", Functional: 0, KernelID: 0x901, Args: []Arg{
			{Index: 0, Name: "opcode", Type: "uint64_t", Offset: 0, Size: 8},
			{Index: 2, Name: "instr_count", Type: "uint32_t", Offset: 16, Size: 4},
			{Index: 1, Name: "instr", Type: "char *", Offset: 8, Size: 8, AddressQualifier: 1},
		}}},
		CUs:         []CU{{Name: "MLIR_AIE:MLIRAIE", KernelID: 0x901}},
		Columns:     1,
		StartCols:   []uint16{0, 1, 2, 3},
		OpsPerCycle: 2048,
		PDIs: []PDI{
			{UUID: [16]byte{9}, Image: []byte("other"), Groups: []CDOGroup{{Name: "other", Type: 1, KernelIDs: []uint64{0x7}}}},
			{UUID: [16]byte{8}, Image: []byte("PDI-IMAGE"), Groups: []CDOGroup{{Name: "DPU", Type: 1, PDIID: 5, KernelIDs: []uint64{0x901}}}},
		},
	}
}

func TestBuildAndParse(t *testing.T) {
	f, err := Parse(Build(spec()))
	if err != nil {
		t.Fatal(err)
	}
	if f.UUID != [16]byte{1, 2, 3} || len(f.Kernels) != 1 || len(f.CUs) != 1 {
		t.Fatalf("%+v", f)
	}
	k := f.Kernels[0]
	if k.Name != "MLIR_AIE" || k.Type != "dpu" || k.KernelID != 0x901 || len(k.Args) != 3 {
		t.Fatalf("kernel %+v", k)
	}
	if k.Args[1].Name != "instr" || !k.Args[1].IsBuffer() || k.Args[1].Offset != 8 || k.Args[2].Size != 4 {
		t.Fatalf("args not sorted by index or wrong: %+v", k.Args)
	}
	if cu := f.CUs[0]; cu.Kernel != "MLIR_AIE" || cu.KernelID != 0x901 || cu.Type != IPPSKernel {
		t.Fatalf("cu %+v", cu)
	}
	p := f.Partition
	if p.Columns != 1 || p.OpsPerCycle != 2048 || len(p.StartColumns) != 4 || p.StartColumns[3] != 3 || len(p.PDIs) != 2 {
		t.Fatalf("partition %+v", p)
	}
	if g := p.PDIs[1].Groups[0]; g.Name != "DPU" || g.PDIID != 5 {
		t.Fatalf("group %+v", g)
	}
	img, ok := f.PDIForKernel(0x901)
	if !ok || !bytes.Equal(img, []byte("PDI-IMAGE")) {
		t.Fatalf("PDI %q %v", img, ok)
	}
	if _, ok := f.PDIForKernel(0x123); ok {
		t.Fatal("unexpected PDI")
	}
}

func TestParseRejectsBadInput(t *testing.T) {
	if _, err := Parse([]byte("not an xclbin")); err == nil {
		t.Fatal("bad magic accepted")
	}
	b := Build(spec())
	if _, err := Parse(b[:600]); err == nil {
		t.Fatal("truncated file accepted")
	}
}
